import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'admin_login_screen.dart';
final _fleetsProvider = FutureProvider.autoDispose((ref) => ref.watch(adminRepositoryProvider).fleets());
class AdminFleetsScreen extends ConsumerWidget { const AdminFleetsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final fleets = ref.watch(_fleetsProvider); return Scaffold(appBar: AppBar(title: const Text('Fleets')), body: fleets.when(loading: () => const Center(child: CircularProgressIndicator()), error: (_, __) => const Center(child: Text('Could not load fleets.')), data: (items) => items.isEmpty ? const Center(child: Text('No fleets created yet.')) : ListView.separated(padding: const EdgeInsets.all(16), itemCount: items.length, separatorBuilder: (_, __) => const SizedBox(height: 10), itemBuilder: (_, i) { final f = items[i] as Map<String,dynamic>; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.groups_outlined)), title: Text(f['name']), subtitle: Text('Owner: ${f['owner_name']} · ${f['owner_phone']}\nDriver: ${f['driver_name'] ?? 'Not assigned'}${f['driver_phone'] == null ? '' : ' · ${f['driver_phone']}'}'), isThreeLine: true)); }))); } }
